# Oracle cases (design 11): tests/testthat/oracle/<Type>.json, generated by
# tools/temporal-oracle/generate.js from temporal-polyfill. oracle_cases()
# reads a file; each type's test file loops over the cases and hands each
# to the checker for that type.

oracle_cases <- function(type) {
  skip_if_not_installed("jsonlite")
  path <- test_path("oracle", paste0(type, ".json"))
  doc <- jsonlite::fromJSON(path, simplifyVector = FALSE)
  stopifnot(identical(doc$type, type))
  doc$cases
}

# The condition class a JavaScript error class maps to (design 10).
oracle_error_class <- function(js) {
  switch(
    js,
    RangeError = "zutempo_range_error",
    TypeError = "zutempo_type_error",
    stop("unmapped JavaScript error class: ", js)
  )
}

# JavaScript property name to the R accessor of design 5.
oracle_accessor <- function(name) {
  name <- gsub("([a-z0-9])([A-Z])", "\\1_\\2", name)
  name <- gsub("([A-Z]+)([A-Z][a-z])", "\\1_\\2", name)
  tolower(name)
}

# A JSON field value as R expects the accessor to return it.
oracle_field_value <- function(value) {
  if (is.null(value)) NA else value
}

# Skip a case whose R functions a later stage builds. The constructor is
# the first function each type gets, so its absence means the type is not
# built yet.
oracle_skip_until_built <- function(constructor, stage) {
  if (!exists(constructor, envir = asNamespace("zutempo"), inherits = FALSE)) {
    skip(sprintf(
      "%s() arrives in stage %d of .agents/roadmap.md",
      constructor,
      stage
    ))
  }
}

# Check one PlainDate case: `from` and `compare` (stage 2).
oracle_check_plain_date <- function(case) {
  oracle_skip_until_built("plain_date", 2L)
  ns <- asNamespace("zutempo")
  plain_date <- get("plain_date", envir = ns)
  if (identical(case$op, "from")) {
    arg <- case$args[[1L]]
    call_from <- function() {
      if (is.character(arg)) {
        do.call(plain_date, c(list(arg), case$options))
      } else {
        do.call(plain_date, c(arg, case$options))
      }
    }
    if (!is.null(case$throws)) {
      expect_error(call_from(), class = oracle_error_class(case$throws))
      return(invisible())
    }
    x <- call_from()
    expect_identical(
      get("temporal_to_string", envir = ns)(x),
      case$result$string
    )
    for (name in names(case$result$fields)) {
      accessor <- get(oracle_accessor(name), envir = ns)
      expect_equal(
        accessor(x),
        oracle_field_value(case$result$fields[[name]]),
        info = name
      )
    }
  } else if (identical(case$op, "compare")) {
    compare <- get("plain_date_compare", envir = ns)
    expect_identical(
      compare(plain_date(case$args[[1L]]), plain_date(case$args[[2L]])),
      as.integer(case$result)
    )
  } else {
    stop("unknown PlainDate op: ", case$op)
  }
  invisible()
}
